// CLEANUP revision of ../solana-onion-relay-service-v2/serve.mjs (qualified, untouched), itself the WINDOWED revision of ../solana-onion-relay-service-v1/serve.mjs.
// The task is the one of ../solana-relay-cleanup-v1: after the pool has settled a payment the relay closes the verifier receipt and then the proof buffer it created
// for that request, so their rent returns to the sponsor. Generated by make_service.py; the whole difference from v2 is that file.
// WINDOWED revision of ../solana-onion-relay-service-v1/serve.mjs (frozen, untouched): the same composition, but the task, the repository, the funding and
// the publication sender are the windowed ones of ../solana-relay-windowed-v1, and the proof buffer is filled WINDOW chunk uploads at a time.
// Relay service composition for the LOCAL onion trial: a sponsor-funded relay behind a loopback HTTP port that a v3
// onion service exposes. Synthetic only. The operator (the Python harness) owns the validator, the faucet that funds
// the sponsor, Tor and the onion name; this process owns the sponsor key, the sponsor journal and the proof admission.
// usage: node serve.mjs STATE_DIR LIVE_CONFIG LIVE_CONFIG_SHA256 NATIVE_PROFILE NATIVE_PROFILE_SHA256 [PORT]   (PORT 0 = any free loopback port;
// a fixed one lets the operator restart the service behind the same onion mapping)
// stdin lines (operator only): `HOST <name>.onion` once, `STOP`.  stdout: one JSON event per line.
import fs from 'node:fs';
import path from 'node:path';
import {randomBytes,createHash} from 'node:crypto';
import {fileURLToPath,pathToFileURL} from 'node:url';
import {createInterface} from 'node:readline';
import {LocalRelayTask} from '../solana-relay-cleanup-v1/relay-task.mjs';
import {RelayRepository} from '../solana-relay-cleanup-v1/relay-repository.mjs';
import {nativeVerifier} from '../solana-private-relay-v1/native-verifier.mjs';
import {readRequest} from '../solana-private-relay-v1/relay-request.mjs';
import {relayOffer} from '../solana-private-relay-v1/relay-offer.mjs';
import {LocalNetwork} from '../solana-relay-performance-v1/candidate/local-network.mjs';
import {createSnapshotValidator} from '../solana-chrome-wallet-v1/extension/snapshot-loader.mjs';
import {privateSigner,b58} from '../solana-chrome-wallet-v1/recovery/solana-transaction.mjs';
import {decodeTransaction as nativeDecode} from '../solana-beta-withdraw-v1/publisher/transport.mjs';
import {requireState as require,hexValue} from '../solana-chrome-wallet-v1/recovery/checkpoint.mjs';
import {createRequestStore} from '../solana-onion-relay-service-v1/relay-store.mjs';
import {createRelayHttp} from '../solana-onion-relay-service-v1/relay-http.mjs';
import {createTaskManager,RelayRefusal} from '../solana-onion-relay-service-v1/relay-tasks.mjs';

const sha=bytes=>createHash('sha256').update(bytes).digest('hex');
// The Rust snapshot/settlement planner used by the qualified relay run (relay-live-04 INPUTS.json).
const ENGINE=Object.freeze({'snapshot.js':'c6d0002a9d0abd60816d0e0614181149e0e14283ca8ed80538c8ba1a8f8bebfd','snapshot_bg.wasm':'b542d7c27dc7ff98122628b493e38d35ee8df88134603ef24ecbee727879d4c5'});
const FUNDING=Object.freeze({totalLamports:'160000000000',requestLamports:'80000000000',maxFeeLamports:'10000'});   // same caps as relay-live-04
// Chunk uploads signed, released and resolved together. Pinned by this file's hash, like every other operator setting.
const WINDOW=64;
// After a settled payment, give the rent of the receipt and of the proof buffer back to the sponsor. Pinned by this file's hash.
const CLEANUP=true;

const [stateDir,configPath,configHash,profilePath,profileHash,portArg='0']=process.argv.slice(2);
const wanted=Number(portArg);
require(/^[0-9]{1,5}$/.test(portArg)&&Number.isInteger(wanted)&&wanted>=0&&wanted<65536,'Valid loopback port or 0 required.');
require(path.isAbsolute(stateDir)&&path.isAbsolute(configPath)&&path.isAbsolute(profilePath),'Absolute paths required.');
hexValue(configHash,32);hexValue(profileHash,32);
const stateStat=fs.lstatSync(stateDir);
require(stateStat.isDirectory()&&!stateStat.isSymbolicLink()&&(stateStat.mode&0o077)===0&&stateStat.uid===process.getuid(),'Relay state needs an owner-only directory.');
const configBytes=fs.readFileSync(configPath);require(sha(configBytes)===configHash,'Live configuration pin mismatch.');
const config=JSON.parse(configBytes);
const {context,program,pool}=config;hexValue(context,96);
const bufferProgram=config.buffer_program,proofProgram=config.proof_program,withdrawProgram=config.withdraw_program;
const programs=[program,bufferProgram,proofProgram,withdrawProgram];
const verifyNative=nativeVerifier(profilePath,profileHash);
// A rejected proof is a refusal with a fixed code, never an internal message.
const verifyProof=async(kind,wire,c)=>{if(await verifyNative(kind,wire,c)!==true)throw new RelayRefusal('invalid_proof');return true;};

const engine=fileURLToPath(new URL('../solana-chrome-wallet-v1/evidence/snapshot-bindings-08/engine/',import.meta.url));
for(const [name,expected] of Object.entries(ENGINE))require(sha(fs.readFileSync(engine+name))===expected,'Pinned snapshot engine changed.');
const {default:initialize}=await import(pathToFileURL(engine+'snapshot.js'));
const pinnedValidator=createSnapshotValidator(await initialize({module_or_path:fs.readFileSync(engine+'snapshot_bg.wasm')}));
let lastSettlement=null;
const validator=request=>pinnedValidator(request);
// Kept in memory only; written out when a task fails so a diagnosis does not need to repeat thousands of transactions.
validator.settlement=request=>{const plan=pinnedValidator.settlement(request);lastSettlement={request,plan};return plan;};

// The sponsor and the transport seed are the relay's, persisted so that a restart derives the very same accounts.
function persistentSeed(name) {
  const file=path.join(stateDir,name);
  try{
    const fd=fs.openSync(file,fs.constants.O_CREAT|fs.constants.O_EXCL|fs.constants.O_WRONLY|fs.constants.O_NOFOLLOW,0o600);
    const seed=randomBytes(32);
    try{fs.writeSync(fd,seed);fs.fsyncSync(fd);}finally{fs.closeSync(fd);}
    return new Uint8Array(seed);
  }catch(error){
    if(error.code!=='EEXIST')throw error;
    const stat=fs.lstatSync(file);
    require(stat.isFile()&&!stat.isSymbolicLink()&&(stat.mode&0o077)===0&&stat.uid===process.getuid()&&stat.size===32,'Unsafe relay seed file.');
    const seed=new Uint8Array(fs.readFileSync(file));require(seed.some(x=>x),'Empty relay seed.');return seed;
  }
}
const sponsor=await privateSigner(persistentSeed('sponsor.seed')),transportSeed=persistentSeed('transport.seed'),authority=b58(sponsor.pub);

const events=fs.openSync(path.join(stateDir,'EVENTS.jsonl'),fs.constants.O_CREAT|fs.constants.O_APPEND|fs.constants.O_WRONLY|fs.constants.O_NOFOLLOW,0o600);
const emit=event=>{
  const line=JSON.stringify({t:new Date().toISOString(),...event})+'\n';
  fs.writeSync(events,line);process.stdout.write(line);
};
fs.mkdirSync(path.join(stateDir,'diagnostics'),{recursive:true,mode:0o700});
const repo=new RelayRepository(path.join(stateDir,'operations.sqlite'));
const store=createRequestStore(stateDir);
const observer=new LocalNetwork({profile:config.network});
let submissions=0;
// Every transaction this relay releases must be paid and signed by its own sponsor; nothing else may leave through here.
const fetchImpl=async(url,options)=>{
  const call=JSON.parse(options.body);
  if(call.method==='sendTransaction') {
    require(b58(nativeDecode(call.params[0]).authority)===authority,'Only the sponsor may pay a relayed transaction.');
    submissions++;
  }
  return fetch(url,options);
};
function dumpDiagnostics(id) {
  if(!lastSettlement)return;
  const prefix=path.join(stateDir,'diagnostics',id.slice(0,16)+'-last-settlement');
  try{
    fs.writeFileSync(prefix+'-REQUEST.json',JSON.stringify(lastSettlement.request)+'\n',{mode:0o600});
    fs.writeFileSync(prefix+'-PLAN.json',JSON.stringify(lastSettlement.plan)+'\n',{mode:0o600});
  }catch{ /* diagnostics are best effort */ }
}
// One line per change of the cleanup phase: which close is being confirmed and in which state.
let lastCleanup=null;
function noteCleanup(id,result) {
  const key=id+'|'+result.step+'|'+result.state;if(key===lastCleanup)return;lastCleanup=key;
  emit({type:'cleanup',id,step:result.step??null,state:result.state});
}
async function openTask(raw,signal) {
  const attested=await observer.attest(programs);
  const task=await LocalRelayTask.open({raw,context,program,pool,profile:config.network,programData:attested.programs,sponsor,transportSeed,
    repository:repo,validator,verifyProof,signal,fetchImpl,funding:FUNDING,window:WINDOW,cleanup:CLEANUP});
  return {
    id:task.id,transport:task.transport,
    async step(){try{const result=await task.step();if(result.phase==='cleanup')noteCleanup(task.id,result);return result;}catch(error){dumpDiagnostics(task.id);throw error;}},
    close:()=>task.close(),
  };
}
const manager=createTaskManager({context,readRequest,openTask,store,emit});
const http=createRelayHttp({
  offer:request=>relayOffer(request,{context,sponsor,transportSeed}),
  submit:raw=>manager.submit(raw),
});
const port=await http.listen(wanted);
const recovered=await manager.recover();
emit({type:'ready',port,authority,recovered,scope:'local-onion-relay-service',window:WINDOW,cleanup:CLEANUP});

let stopping=false;
async function stop(code) {
  if(stopping)return;stopping=true;
  await manager.stop();await http.close();repo.close();
  emit({type:'stopped',submissions});
  process.exit(code);
}
const lines=createInterface({input:process.stdin});
lines.on('line',line=>{
  if(line==='STOP'){stop(0);return;}
  const match=/^HOST ([a-z2-7]{56}\.onion)$/.exec(line);
  if(!match){emit({type:'control_error'});stop(1);return;}
  try{http.setHost(match[1]);emit({type:'host_bound'});}catch{emit({type:'control_error'});stop(1);}
});
lines.on('close',()=>stop(0));
process.once('SIGTERM',()=>stop(0));process.once('SIGINT',()=>stop(0));
process.once('uncaughtException',error=>{try{emit({type:'fatal',message:String(error?.message).slice(0,200)});}catch{ /* nothing left */ }process.exit(1);});
